import json
def solve(g):
    H,W=len(g),len(g[0])
    vals=[v for row in g for v in row]
    bg=max(set(vals),key=vals.count)
    seen=[[False]*W for _ in range(H)]
    q=deque()
    for r in range(H):
        for c in range(W):
            if (r in(0,H-1) or c in(0,W-1)) and g[r][c]==bg:
                seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in((-1,0),(1,0),(0,-1),(0,1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and not seen[rr][cc] and g[rr][cc]==bg:
                seen[rr][cc]=True; q.append((rr,cc))
    return [[4 if g[r][c]==bg and not seen[r][c] else g[r][c] for c in range(W)] for r in range(H)]
